function renderPERange(v){
  const numeric=x=>typeof x==='number'&&Number.isFinite(x);
  const low=v&&v.pe_low,high=v&&v.pe_high,position=v&&v.pe_pctile;
  const open='<span class="pe-range-context" style="max-width:100%;overflow-wrap:anywhere;white-space:normal" title="Position within the reported positive annual P/E min-max range (0-100%, clamped), not a percentile.">';
  const close='<small style="display:block;font-size:inherit">Reported annual range; window and comparability unverified.</small></span>';
  if(!numeric(low)||!numeric(high)||low<=0||high<low)return open+'P/E range unavailable'+close;
  const value=high>low&&numeric(position)&&position>=0&&position<=100?position+'%':'unavailable';
  return open+'P/E range <b>'+low+'–'+high+'×</b> · position <b>'+value+'</b>'+close;
}
